function firstUnique(s) {
  var counts = {};
  for (var i = 0; i < s.length; i++) {
    counts[s[i]] = (counts[s[i]] || 0) + 1;
  }
  for (var j = 0; j < s.length; j++) {
    if (counts[s[j]] === 1) {
      return j;
    }
  }
  return -1;
}

console.log(firstUnique("leetcode"));
